process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 10 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2; }
pa() { for i in 1 2 3; do s=$(p "$1"); [ "$s" = 502 ] || break; sleep 2; done; echo "$s"; }
echo NO_PROXY=$NO_PROXY
echo HOST_DNS=$(nslookup host.wslc.internal 2>/dev/null | awk '/^Address/ { a = $NF } END { print a }')
echo HOST_DIRECT=$(printf 'GET / HTTP/1.0\r\n\r\n' | nc -w 10 host.wslc.internal 18890 | head -n1 | cut -d' ' -f2)
echo HOST_VIA_PROXY=$(pa host.wslc.internal:18890)
echo LOOPBACK=$(p 127.0.0.1:18890)
echo ALLOWED=$(pa 1.1.1.1:443)
echo DENIED=$(p 8.8.8.8:443)
nc -z -w 3 1.1.1.1 443 && echo DIRECT=REACHED || echo DIRECT=BLOCKED
